package ai.graine.inapp

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertSame
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.util.TreeMap

/**
 * THE DESIGN CONTRACT: real session `design` objects, resolved by theme.ts
 * itself (sdk/contract/design.json, generated by generate-design.mjs). This
 * SDK never resolves a philosophy, so what it must prove is that it READS
 * every token exactly, picks light or dark the same way, and asks for the
 * same glyph image — the same answers the web, React Native, iOS and Flutter
 * give from the same file.
 */
class DesignTest {
    private val fx: JSONObject by lazy {
        var dir: File? = File("").absoluteFile
        while (dir != null && !File(dir, "sdk/contract/design.json").exists() && !File(dir, "contract/design.json").exists()) {
            dir = dir.parentFile
        }
        val f = listOf(File(dir, "sdk/contract/design.json"), File(dir, "contract/design.json")).firstOrNull { it.exists() }
            ?: error("sdk/contract/design.json missing — run sdk/contract/generate-design.mjs")
        JSONObject(f.readText())
    }

    private fun cases(): List<JSONObject> = fx.getJSONArray("cases").let { a -> (0 until a.length()).map { a.getJSONObject(it) } }

    /** Every design in the file: each case's, and what a legacy embed's session says. */
    private fun designs(): List<JSONObject> = cases().map { it.getJSONObject("design") } + fx.getJSONObject("legacy").getJSONObject("design")

    /** JSON in one comparable shape: numbers as doubles, keys sorted, JSON null as null. */
    private fun canon(v: Any?): Any? = when {
        v == null || v == JSONObject.NULL -> null
        v is JSONObject -> TreeMap<String, Any?>().also { m -> v.keys().forEach { k -> m[k] = canon(v.opt(k)) } }
        v is JSONArray -> (0 until v.length()).map { canon(v.opt(it)) }
        v is Number -> v.toDouble()
        else -> v
    }

    private fun parse(o: JSONObject): ResolvedDesign = ResolvedDesign.parse(o) ?: error("did not parse: $o")

    /** The case whose knobs include all of these, whatever order the file lists them in. */
    private fun caseWith(vararg knobs: Pair<String, Any>): JSONObject = cases().first { c ->
        val config = c.getJSONObject("config")
        knobs.all { (k, v) -> config.opt(k) == v }
    }.getJSONObject("design")

    /** Every knob turned: dark, hard shadow, glass, outline bubbles, the logo on a pill. */
    private val hardCase by lazy { caseWith("shadow" to "hard", "launcherShape" to "pill", "scheme" to "dark") }
    /** The other way: light, no shadow, lively, minimal bubbles, a squircle. */
    private val softCase by lazy { caseWith("shadow" to "none", "launcherShape" to "squircle", "scheme" to "light") }
    /** Graine Classic as it comes. */
    private val classicCase by lazy { cases().first { it.getJSONObject("config").let { c -> c.length() == 1 && c.optString("preset") == Design.DEFAULT_PRESET } }.getJSONObject("design") }

    @Test fun theFileHasSomethingToProve() {
        assertTrue(cases().size >= 3)
        assertEquals(2, fx.getJSONArray("glyphs").length())
    }

    @Test fun readsEveryTokenOfEveryDesignExactly() {
        for (d in designs()) {
            // Written back out, the parsed design is the design: nothing lost, nothing invented, nothing rounded.
            assertEquals("config ${d.getJSONObject("config")}", canon(d), canon(parse(d).toJson()))
        }
    }

    @Test fun meetsEveryKindOfTokenTheDashboardCanProduce() {
        val all = designs().map { parse(it) }.flatMap { listOf(it.light, it.dark) }
        // Not a claim about any one philosophy: proof the file exercised each shape the parser must survive.
        assertTrue(all.map { it.shape.launcher }.toSet().containsAll(listOf("circle", "pill", "squircle")))
        assertTrue(all.map { it.bubbles }.toSet().containsAll(listOf("filled", "outline", "minimal")))
        assertTrue("plain surfaces and windows", all.map { it.chrome }.toSet().containsAll(listOf("none", "window")))
        assertTrue("glass", all.any { it.glass != null })
        assertTrue("a hard offset", all.any { it.elevation.hardOffset != null })
        assertTrue("no card shadow", all.any { it.elevation.card == null })
        assertTrue("the logo instead of a glyph", all.any { it.icons.launcher == null })
        assertTrue("a hairline outline", all.any { it.shape.borderWidth == 0.5 })
        assertTrue("a family the app may not bundle", all.any { Design.fontFamily(it.font.heading) != null })
        // Whatever the design, an unmapped family is the system font, never an error.
        for (t in all) assertNull(Design.fontFor(emptyMap<String, Any>(), t.font.heading))
    }

    @Test fun readsTheTokensItDrawsWithAsTheirOwnTypes() {
        val hard = parse(hardCase).dark
        assertEquals("dark", hard.scheme)
        assertEquals("#FFE600", hard.colors.accent)
        assertEquals("pill", hard.shape.launcher)
        assertEquals(2.0, hard.shape.borderWidth, 0.0)
        assertEquals(0.0, hard.shape.radius.lg, 0.0)
        assertEquals(ThemeOffset(4.0, 4.0), hard.elevation.hardOffset)
        assertNull(hard.elevation.card)
        assertNull(hard.elevation.floating)
        assertEquals(ThemeGlass(20.0, 0.72), hard.glass)
        assertNull("the brand's logo, not a glyph", hard.icons.launcher)
        assertEquals("outline", hard.bubbles)
        assertEquals(0, hard.motion.durationMs)
        assertEquals("every knob turned opens in windows", "window", hard.chrome)
        assertEquals("window", parse(hardCase).config.chrome)

        val soft = parse(softCase).light
        assertEquals("squircle", soft.shape.launcher)
        assertEquals("minimal", soft.bubbles)
        assertEquals("none", soft.chrome)
        assertNull("a knob not turned", parse(softCase).config.chrome)
        assertEquals(ThemeMotion(320, "spring", 0.3), soft.motion)
        val glyph = softCase.getJSONObject("light").getJSONObject("icons").getJSONObject("launcher")
        assertEquals(LauncherGlyph(glyph.getString("id"), glyph.getString("path"), glyph.getBoolean("stroke")), soft.icons.launcher)
        assertNull(soft.glass)
        assertNull(soft.elevation.hardOffset)
    }

    @Test fun picksLightOrDarkAsTheContractSays() {
        for (c in cases()) {
            val d = parse(c.getJSONObject("design"))
            val picks = c.getJSONObject("picks")
            assertEquals("${c.get("config")} on a light phone", picks.getString("deviceLight"), d.pick(false).scheme)
            assertEquals("${c.get("config")} on a dark phone", picks.getString("deviceDark"), d.pick(true).scheme)
            assertEquals("${c.get("config")} on a phone that will not say", picks.getString("deviceUnknown"), d.pick(null).scheme)
        }
    }

    @Test fun aHostsOwnSchemeWinsOverTheBrands() {
        val fixedDark = parse(hardCase)
        assertEquals("light", fixedDark.pick(true, "light").scheme)
        assertEquals("light", fixedDark.pick(false, "auto").scheme)
        assertEquals("dark", fixedDark.pick(false, "nonsense").scheme)
        assertEquals("dark", fixedDark.pick(false, null).scheme)
    }

    @Test fun asksForTheSameGlyphImage() {
        val glyphs = fx.getJSONArray("glyphs")
        for (i in 0 until glyphs.length()) {
            val g = glyphs.getJSONObject(i)
            val a = g.getJSONArray("args")
            val got = Design.glyphUrl(a.getString(0), a.getString(1), a.getString(2), a.getDouble(3), a.getDouble(4))
            assertEquals("args $a", g.getString("url"), got)
        }
    }

    @Test fun theGlyphAddressClampsAsTheImageEndpointDoes() {
        assertEquals("https://www.graine.ai/api/embed/glyph?id=mic&c=FFFFFF&s=16&w=0.5&v=2", Design.glyphUrl(null, " Mic ", "nope", 3.0, 0.1))
        assertEquals("https://www.graine.ai/api/embed/glyph?id=mic&c=101318&s=96&w=2&v=2", Design.glyphUrl("", "mic", "#101318", 0.0, 0.0))
        // Quarter steps: 2.3 is asked for as 2.25, 1.9 as 2.
        assertEquals("https://x.test/api/embed/glyph?id=mic&c=101318&s=67&w=2.25&v=2", Design.glyphUrl("https://x.test//", "mic", "101318", 66.5, 2.3))
        assertEquals("https://x.test/api/embed/glyph?id=a%20b&c=101318&s=64&w=2&v=2", Design.glyphUrl("https://x.test", "A B", "#101318", 64.0, 1.9))
    }

    @Test fun unknownKeysAreIgnoredEverywhere() {
        val original = classicCase
        val noisy = JSONObject(original.toString())
        noisy.put("philosophyNotes", "from a newer server")
        noisy.getJSONObject("config").put("sparkle", 11)
        for (scheme in listOf("light", "dark")) {
            val t = noisy.getJSONObject(scheme)
            t.put("haptics", JSONObject().put("tap", "light"))
            t.getJSONObject("colors").put("link", "#0000EE")
            t.getJSONObject("font").getJSONObject("scale").put("huge", 64)
            t.getJSONObject("elevation").getJSONObject("card").put("inset", true)
            t.getJSONObject("icons").getJSONObject("launcher").put("label", "Waveform")
            t.getJSONObject("shape").getJSONObject("radius").put("xxl", 64)
        }
        assertEquals(canon(original), canon(parse(noisy).toJson()))
    }

    @Test fun anythingThatIsNotADesignIsNull() {
        for (raw in listOf<Any?>(null, "", "not json", "[1,2]", 42, true, JSONArray(), JSONObject(), JSONObject.NULL,
            JSONObject().put("light", 5).put("dark", "dark"),
            JSONObject().put("light", JSONObject()).put("dark", JSONObject().put("font", JSONObject())),
            JSONObject().put("config", JSONObject().put("preset", "graine-classic")),
        )) {
            assertNull("raw: $raw", ResolvedDesign.parse(raw))
        }
    }

    @Test fun itsJsonTextParsesToo() {
        val d = softCase
        assertEquals(canon(d), canon(ResolvedDesign.parse(d.toString())!!.toJson()))
    }

    @Test fun aMissingSchemeBorrowsTheOther() {
        val d = JSONObject(classicCase.toString())
        d.remove("dark")
        val parsed = parse(d)
        assertEquals("dark", parsed.dark.scheme)
        assertEquals(parsed.light.colors, parsed.dark.colors)
    }

    @Test fun aMalformedValueTakesGraineClassicsAndNeverThrows() {
        val d = JSONObject(hardCase.toString())
        val light = d.getJSONObject("light")
        light.getJSONObject("colors").put("accent", "yellow").put("text", 12).put("surface", "#abc")
        light.getJSONObject("shape").put("launcher", "hexagon").put("borderWidth", "thick")
        light.getJSONObject("shape").getJSONObject("radius").put("lg", JSONObject.NULL)
        light.getJSONObject("font").getJSONObject("weights").put("title", 5000)
        light.getJSONObject("motion").put("easing", "wobbly").put("durationMs", -40)
        light.getJSONObject("elevation").put("hardOffset", "yes")
        light.put("glass", "frosted")
        light.put("bubbles", 3)
        light.put("chrome", "skeuomorphic")
        light.remove("icons")
        val t = parse(d).light
        val classic = Design.CLASSIC_LIGHT
        assertEquals(classic.colors.accent, t.colors.accent)
        assertEquals(classic.colors.text, t.colors.text)
        assertEquals("a short hex is still a colour", "#AABBCC", t.colors.surface)
        assertEquals(classic.shape.launcher, t.shape.launcher)
        assertEquals(classic.shape.borderWidth, t.shape.borderWidth, 0.0)
        assertEquals(classic.shape.radius.lg, t.shape.radius.lg, 0.0)
        assertEquals(900, t.font.weights.title)
        assertEquals("standard", t.motion.easing)
        assertEquals(0, t.motion.durationMs)
        assertNull("a hard offset that is not one is the default: none", t.elevation.hardOffset)
        assertNull(t.glass)
        assertEquals("filled", t.bubbles)
        assertEquals("a chrome this build does not know is a plain surface", "none", t.chrome)
        assertEquals(classic.icons, t.icons)
        // What was fine is untouched.
        assertEquals("#FFE600", parse(d).dark.colors.accent)
        assertEquals("window", parse(d).dark.chrome)
    }

    @Test fun graineClassicsDefaultsAreWhatTheServerResolves() {
        val d = classicCase
        assertEquals(canon(d.getJSONObject("light")), canon(Design.CLASSIC_LIGHT.toJson()))
        assertEquals(canon(d.getJSONObject("dark")), canon(Design.CLASSIC_DARK.toJson()))
    }

    @Test fun theLaunchersCornersFollowItsShape() {
        val r = ThemeRadius(8.0, 12.0, 18.0, 24.0)
        assertEquals(28.0, Design.launcherCorner("circle", 56.0, r), 1e-9)
        assertEquals(28.0, Design.launcherCorner("pill", 56.0, r), 1e-9)
        assertEquals(16.8, Design.launcherCorner("squircle", 56.0, r), 1e-9)
        assertEquals(18.0, Design.launcherCorner("rounded-square", 56.0, r), 1e-9)
        assertEquals(8.0, Design.launcherCorner("square", 56.0, r), 1e-9)
        // Never past fully round, however large the design's corners.
        assertEquals(28.0, Design.launcherCorner("rounded-square", 56.0, ThemeRadius(16.0, 24.0, 36.0, 48.0)), 1e-9)
        assertEquals(28.0, Design.launcherCorner(null, 56.0, r), 1e-9)
    }

    @Test fun motionIsTheDesignsDurationUnlessAnyoneSaysNone() {
        val lively = ThemeMotion(320, "spring", 0.3)
        assertEquals(320L, Design.motionMs(lively, 1f))
        assertEquals("the phone's scale is applied by the animator itself", 320L, Design.motionMs(lively, 0.5f))
        assertEquals("animations off on the phone", 0L, Design.motionMs(lively, 0f))
        assertEquals(0L, Design.motionMs(ThemeMotion(0, "none", 0.0), 1f))
        assertEquals(0L, Design.motionMs(ThemeMotion(200, "none", 0.0), 1f))
        assertEquals("no design: the look before designs had no transitions", 0L, Design.motionMs(null, 1f))
    }

    @Test fun aShadowTokenBecomesAnElevationAndAnAlpha() {
        assertEquals(0.0 to 0.0, Design.androidShadow(null))
        val (elevation, alpha) = Design.androidShadow(ThemeShadow(8.0, 24.0, 0.0, 0.16, "#000000"))
        assertEquals(8.0, elevation, 0.0)
        assertEquals(0.16 / 0.19, alpha, 1e-9)
        assertEquals(1.0, Design.androidShadow(ThemeShadow(16.0, 40.0, -4.0, 0.5, "#000000")).second, 0.0)
    }

    @Test fun aFontIsUsedOnlyWhenTheAppMappedIt() {
        val fonts = mapOf("Inter" to "inter.ttf", " Playfair Display " to "playfair.ttf")
        assertEquals("inter.ttf", Design.fontFor(fonts, "Inter"))
        assertEquals("inter.ttf", Design.fontFor(fonts, "inter"))
        assertEquals("playfair.ttf", Design.fontFor(fonts, "Playfair Display"))
        assertNull(Design.fontFor(fonts, "Lora"))
        assertNull(Design.fontFor(fonts, "system"))
        assertNull(Design.fontFor(fonts, null))
        assertNull(Design.fontFor(mapOf("system" to "no.ttf"), "System"))
    }

    @Test fun aSessionWithoutADesignKeepsTheAppearance() {
        val s = SessionConfig("a", "a", JSONObject().put("accent", "#7C3AED"), emptyMap(), null, emptySet())
        assertNull(s.design)
        val withDesign = s.copy(design = parse(fx.getJSONObject("legacy").getJSONObject("design")))
        assertNotNull(withDesign.design)
        // An embed that never chose a design is Graine Classic with its old accent, corners and theme.
        assertEquals("#7C3AED", withDesign.design!!.pick(false).colors.accent)
        assertEquals(9.0, withDesign.design!!.pick(false).shape.radius.lg, 0.0)
        assertEquals("dark", withDesign.design!!.pick(false).scheme)
    }

    @Test fun normalisesAColourAsThemeTsDoes() {
        assertEquals("#AABBCC", Design.normaliseHex("#abc"))
        assertEquals("#AABBCC", Design.normaliseHex(" aabbcc "))
        assertNull(Design.normaliseHex("#abcd"))
        assertNull(Design.normaliseHex(null))
        assertSame(null, Design.normaliseHex("blue"))
    }
}
